<?php get_header(); ?><main class="content-wrap"><h1><?php echo is_home() ? 'Berita & Pengumuman' : esc_html(get_bloginfo('name')); ?></h1><?php if(have_posts()): ?><div class="cards"><?php while(have_posts()):the_post(); ?><article class="card"><?php if(has_post_thumbnail()) the_post_thumbnail('medium'); ?><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><small><?php echo esc_html(get_the_date()); ?></small><?php the_excerpt(); ?></article><?php endwhile; ?></div><?php the_posts_pagination(); else: ?><p>Konten belum tersedia.</p><?php endif; ?></main><?php get_footer(); ?>